import{c as d,Q as e,j as a,m as o}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"快速参考","description":"Claude Code 常用命令、快捷键、配置速查","frontmatter":{"title":"快速参考","description":"Claude Code 常用命令、快捷键、配置速查"},"headers":[],"relativePath":"guide/cheatsheet.md","filePath":"guide/cheatsheet.md"}'),c={name:"guide/cheatsheet.md"};function r(s,t,i,l,n,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="claude-code-快速参考" tabindex="-1">Claude Code 快速参考 <a class="header-anchor" href="#claude-code-快速参考" aria-label="Permalink to &quot;Claude Code 快速参考&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">随时查阅</p><p>忘了就来这里查。全部条目都已按当前版本校对过。</p></div><h2 id="会话里最常用的-8-个命令" tabindex="-1">会话里最常用的 8 个命令 <a class="header-anchor" href="#会话里最常用的-8-个命令" aria-label="Permalink to &quot;会话里最常用的 8 个命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th><th>什么时候按</th></tr></thead><tbody><tr><td><code>/init</code></td><td>生成 <code>CLAUDE.md</code></td><td>第一次进项目</td></tr><tr><td><code>/context</code></td><td>看上下文占用</td><td>变慢、变糊涂的时候</td></tr><tr><td><code>/compact</code></td><td>压缩对话历史</td><td>同一任务聊太长了</td></tr><tr><td><code>/clear</code></td><td>清空对话（保留项目记忆）</td><td>换任务</td></tr><tr><td><code>/rewind</code></td><td>回滚代码 + 对话</td><td>改坏了</td></tr><tr><td><code>/diff</code></td><td>看当前改动的差异面板</td><td>提交前</td></tr><tr><td><code>/code-review</code></td><td>审查当前分支改动</td><td>提交前（<code>/review</code> 是它的别名）</td></tr><tr><td><code>/plan</code></td><td>进入计划模式</td><td>大改动之前</td></tr></tbody></table><h2 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>claude --continue</code></td><td>接着当前目录最近一次会话</td></tr><tr><td><code>claude --resume</code></td><td>打开会话列表挑一个</td></tr><tr><td><code>/resume</code></td><td>在会话内切换到另一个会话</td></tr><tr><td><code>/branch</code></td><td>从当前对话分叉，试另一个方向</td></tr><tr><td><code>/subtask &lt;任务&gt;</code></td><td>分叉去干旁支活，主对话继续</td></tr><tr><td><code>/fork</code></td><td>复制对话到后台会话</td></tr><tr><td><code>/recap</code></td><td>生成当前会话的一句话摘要</td></tr><tr><td><code>/export</code></td><td>导出对话为文本</td></tr><tr><td><code>/exit</code></td><td>退出</td></tr></tbody></table><h2 id="权限与安全" tabindex="-1">权限与安全 <a class="header-anchor" href="#权限与安全" aria-label="Permalink to &quot;权限与安全&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令 / 按键</th><th>用途</th></tr></thead><tbody><tr><td><code>Shift + Tab</code></td><td>循环权限模式：auto → manual → accept edits → plan</td></tr><tr><td><code>/permissions</code></td><td>管理 allow / ask / deny 规则</td></tr><tr><td><code>/sandbox</code></td><td>配置 Bash 沙箱（目录与网络白名单）</td></tr></tbody></table><p>五种模式速记：</p><ul><li><strong>auto</strong>（默认）— 安全的自己做，危险的问你</li><li><strong>manual</strong>（<code>default</code>）— 每条都问</li><li><strong>acceptEdits</strong> — 改文件不问</li><li><strong>plan</strong> — 只出方案，不改代码</li><li><strong>bypassPermissions</strong> — 全不问，只在容器里用</li></ul><h2 id="上下文与成本" tabindex="-1">上下文与成本 <a class="header-anchor" href="#上下文与成本" aria-label="Permalink to &quot;上下文与成本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/context</code></td><td>上下文占用明细，找浪费</td></tr><tr><td><code>/compact [重点]</code></td><td>压缩历史，可指定保留重点</td></tr><tr><td><code>/usage</code></td><td>额度用量（<code>/cost</code> 是其别名）</td></tr><tr><td><code>/autocompact</code></td><td>调整自动压缩的触发窗口</td></tr><tr><td><code>/status</code></td><td>当前模型、配置等状态</td></tr></tbody></table><h2 id="模型与推理强度" tabindex="-1">模型与推理强度 <a class="header-anchor" href="#模型与推理强度" aria-label="Permalink to &quot;模型与推理强度&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sonnet</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 切模型：best / fable / opus / sonnet / haiku</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/effort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> high</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 推理强度：low → medium → high → xhigh → max</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">别记具体版本号</p><p>模型会持续更新，用别名（<code>opus</code> / <code>sonnet</code> / <code>haiku</code>）就不会过时。</p></div><h2 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to &quot;扩展&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/memory</code></td><td>编辑 <code>CLAUDE.md</code>、查看自动记忆</td></tr><tr><td><code>/hooks</code></td><td>查看 hook 配置</td></tr><tr><td><code>/mcp</code></td><td>管理 MCP 服务器连接与授权</td></tr><tr><td><code>@&quot;名字 (agent)&quot;</code></td><td>点名派某个 subagent</td></tr><tr><td><code>claude --agent &lt;名字&gt;</code></td><td>整个会话以某个 subagent 身份运行</td></tr><tr><td><code>claude --worktree &lt;名&gt;</code></td><td>在独立 git worktree 里开会话</td></tr></tbody></table><h2 id="常用-prompt-模板" tabindex="-1">常用 Prompt 模板 <a class="header-anchor" href="#常用-prompt-模板" aria-label="Permalink to &quot;常用 Prompt 模板&quot;">​</a></h2><h3 id="代码审查" tabindex="-1">代码审查 <a class="header-anchor" href="#代码审查" aria-label="Permalink to &quot;代码审查&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/code-review --fix</span></span>
<span class="line"><span>重点关注：安全漏洞、潜在的 bug</span></span></code></pre></div><h3 id="大改动前的计划" tabindex="-1">大改动前的计划 <a class="header-anchor" href="#大改动前的计划" aria-label="Permalink to &quot;大改动前的计划&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plan 把 auth 模块从 session 改成 JWT，列出涉及文件和迁移步骤，先别改</span></span></code></pre></div><h3 id="不需要进历史的旁支问题" tabindex="-1">不需要进历史的旁支问题 <a class="header-anchor" href="#不需要进历史的旁支问题" aria-label="Permalink to &quot;不需要进历史的旁支问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/btw 这个项目为什么用 pnpm 而不是 npm？</span></span></code></pre></div><h3 id="批量操作-先要清单" tabindex="-1">批量操作（先要清单） <a class="header-anchor" href="#批量操作-先要清单" aria-label="Permalink to &quot;批量操作（先要清单）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把 src/components 下所有 .js 改成 .jsx 并更新引用。</span></span>
<span class="line"><span>先列出要改的文件清单和影响范围，等我确认再动手。</span></span></code></pre></div><h3 id="让它自己验收" tabindex="-1">让它自己验收 <a class="header-anchor" href="#让它自己验收" aria-label="Permalink to &quot;让它自己验收&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>改完后跑 npm test 和 npm run lint，全绿了再告诉我</span></span></code></pre></div><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>中断当前生成</td></tr><tr><td><code>Esc</code> <code>Esc</code></td><td>打开回滚菜单（等同 <code>/rewind</code>）</td></tr><tr><td><code>Shift + Tab</code></td><td>切换权限模式</td></tr><tr><td><code>Ctrl + C</code></td><td>中断 / 连按两次退出</td></tr><tr><td><code>Ctrl + D</code></td><td>退出</td></tr><tr><td><code>Ctrl + G</code></td><td>把计划拉到编辑器里改</td></tr><tr><td><code>Ctrl + L</code></td><td>清屏</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>历史命令</td></tr><tr><td><code>@</code></td><td>引用文件</td></tr><tr><td><code>!</code></td><td>直接执行 shell 命令</td></tr></tbody></table><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>ANTHROPIC_BASE_URL</code></td><td>自定义 API 端点（中转用）</td><td><code>https://api.minimaxi.com/anthropic</code></td></tr><tr><td><code>ANTHROPIC_AUTH_TOKEN</code></td><td>中转服务的密钥</td><td><code>sk-...</code></td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>官方 API 密钥</td><td><code>sk-ant-...</code></td></tr><tr><td><code>ANTHROPIC_MODEL</code></td><td>默认模型</td><td><code>MiniMax-M3</code></td></tr><tr><td><code>CLAUDE_CONFIG_DIR</code></td><td>独立配置目录（多账号并行）</td><td><code>~/.claude-work</code></td></tr><tr><td><code>DISABLE_AUTOUPDATER</code></td><td>关闭自动更新检查</td><td><code>1</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">别记错名字</p><p>前缀是 <strong><code>ANTHROPIC_</code></strong>，不是 <code>CLAUDE_</code>。把它写进 <code>~/.claude/settings.json</code> 的 <code>env</code> 字段可以永久生效。</p></div><h2 id="命令行参数" tabindex="-1">命令行参数 <a class="header-anchor" href="#命令行参数" aria-label="Permalink to &quot;命令行参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>claude</code></td><td>交互式启动</td></tr><tr><td><code>claude -p &quot;...&quot;</code></td><td>非交互模式，输出后退出（可管道输入）</td></tr><tr><td><code>claude --continue</code></td><td>接着上次会话</td></tr><tr><td><code>claude --resume</code></td><td>从列表恢复会话</td></tr><tr><td><code>claude --model opus</code></td><td>指定模型</td></tr><tr><td><code>claude --permission-mode plan</code></td><td>指定启动权限模式</td></tr><tr><td><code>claude --worktree &lt;名&gt;</code></td><td>在独立 worktree 里开</td></tr><tr><td><code>claude --chrome</code></td><td>启用浏览器集成</td></tr><tr><td><code>claude doctor</code></td><td>体检安装与配置</td></tr><tr><td><code>claude update</code></td><td>升级到最新版</td></tr><tr><td><code>claude auth login</code></td><td>登录</td></tr></tbody></table><h2 id="文件操作技巧" tabindex="-1">文件操作技巧 <a class="header-anchor" href="#文件操作技巧" aria-label="Permalink to &quot;文件操作技巧&quot;">​</a></h2><ul><li><strong>直接指定位置</strong>：<code>修改 src/utils/auth.ts 中的登录函数</code></li><li><strong>描述你要做什么</strong>：<code>在 components 目录新建一个 Button 组件</code></li><li><strong>让它自己找</strong>：<code>找出项目里所有使用 fetch 的地方</code></li><li><strong>精确引用</strong>：<code>@src/auth/login.ts 这里的超时是怎么设的？</code></li></ul><h2 id="调试技巧" tabindex="-1">调试技巧 <a class="header-anchor" href="#调试技巧" aria-label="Permalink to &quot;调试技巧&quot;">​</a></h2><ul><li><strong>贴完整错误</strong>：直接粘贴报错全文和触发命令</li><li><strong>先要解释</strong>：<code>先解释这个报错的原因，别改代码</code></li><li><strong>给验收标准</strong>：<code>修完后跑 npm test，把失败的那条贴给我看</code></li><li><strong>卡住就回滚</strong>：<code>/rewind</code> 比硬着头皮改快得多</li></ul><hr><p><a href="/claude-code-guide/">👈 返回首页</a>　　<a href="/claude-code-guide/guide/1-getting-started/1-what-is-claude-code.html">👉 开始学习</a></p>`,41)])])}const b=d(c,[["render",r]]);export{u as __pageData,b as default};
